struct Writer { virtual void write(std::string_view) = 0; virtual ~Writer() = default; };

class CountingWriter : public Writer {          // wrapper shares the interface
public:
  explicit CountingWriter(Writer& inner) : inner_{inner} {}   // delegate injected
  void write(std::string_view s) override { ++count_; inner_.write(s); }
  std::size_t count() const { return count_; }
private:
  Writer& inner_;                               // hand-written forwarding member
  std::size_t count_{};
};

