class RetryWriter {
public:
  explicit RetryWriter(std::function<void(std::string_view)> delegate)
      : delegate_{std::move(delegate)} {}
  void write(std::string_view s) {
    for (int attempt = 0; attempt < 3; ++attempt) {
      try { delegate_(s); return; } catch (...) { /* retry */ }
    }
  }
private:
  std::function<void(std::string_view)> delegate_;   // type-erased delegate
};
